css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .68); position: relative; }
.loader::before, .loader::after { content: ''; position: absolute; bottom: 0; width: 6%; height: 100%; border-radius: 3px; background: linear-gradient(#cbd5e1, #64748b); }
.loader::before { left: 9%; }
.loader::after { right: 9%; }
.loader .bar { position: absolute; left: 3%; width: 94%; height: 7%; border-radius: 999px; background: linear-gradient(#f1f5f9, #94a3b8); animation: lift calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
.loader .bar::before, .loader .bar::after { content: ''; position: absolute; top: -170%; width: 11%; height: 440%; border-radius: 4px; background: linear-gradient(var(--accent), var(--accent-2)); }
.loader .bar::before { left: 0; }
.loader .bar::after { right: 0; }
@keyframes lift { 0%, 100% { bottom: 14%; } 46%, 54% { bottom: 72%; } }
